solution.solution.cpp:
#include <string>

struct Needs
{
    bool otherLanguages{ false };
    bool loadWhileRunning{ false };
    bool updateSeparately{ false };
    bool mostlyTemplates{ false };
    bool small{ false };
};

std::string choosePackage(const Needs& needs)
{
    if (needs.otherLanguages) return "DLL with a C interface";
    if (needs.loadWhileRunning || needs.updateSeparately) return "DLL";
    if (needs.mostlyTemplates || needs.small) return "header-only";
    return "static library";
}

unitTests:
TEST("other languages") { Needs n; n.otherLanguages = true; n.small = true; CHECK_EQ(choosePackage(n), std::string("DLL with a C interface")); }
TEST("plugins") { Needs n; n.loadWhileRunning = true; CHECK_EQ(choosePackage(n), std::string("DLL")); }
TEST("separate updates") { Needs n; n.updateSeparately = true; n.mostlyTemplates = true; CHECK_EQ(choosePackage(n), std::string("DLL")); }
TEST("templates") { Needs n; n.mostlyTemplates = true; CHECK_EQ(choosePackage(n), std::string("header-only")); }
TEST("small") { Needs n; n.small = true; CHECK_EQ(choosePackage(n), std::string("header-only")); }
TEST("nothing special") { CHECK_EQ(choosePackage(Needs{}), std::string("static library")); }

